import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    m, n = map(int, data[:2])

    is_prime = bytearray(b'\x01') * (n + 1)

    if n >= 0:
        is_prime[0] = 0
    if n >= 1:
        is_prime[1] = 0

    i = 2
    while i * i <= n:
        if is_prime[i]:
            start = i * i
            count = (n - start) // i + 1
            is_prime[start:n + 1:i] = b'\x00' * count
        i += 1

    result = [str(i) for i in range(m, n + 1) if is_prime[i]]
    sys.stdout.write("\n".join(result))
    if result:
        sys.stdout.write("\n")

if __name__ == "__main__":
    main()
